"""Routes for Seed Catalog, generated by Dryv; the engine implements CatalogSeedCatalogService."""

from __future__ import annotations

from abc import ABC, abstractmethod
from collections.abc import Awaitable, Callable
from typing import Annotated

from fastapi import APIRouter, Depends, Query, Request

from mzizi_engine.api.schemas.api.catalog.models.seed_catalog import SeedCatalog

__all__ = ["CatalogSeedCatalogService", "build_catalog_seed_catalog_router"]

type Guard = Callable[[Request], Awaitable[None]]
"""An async FastAPI dependency that raises 401 or 403 before the route runs."""


class CatalogSeedCatalogService(ABC):
    """What Seed Catalog needs from handwritten code. Raise ``fastapi.HTTPException`` for failures."""

    @abstractmethod
    async def get_seed_catalog(self, *, table: str | None) -> SeedCatalog:
        """Read the generated seed contract catalog, optionally filtered by table."""


def build_catalog_seed_catalog_router(service: CatalogSeedCatalogService, guard: Guard | None = None) -> APIRouter:
    """Routes for Seed Catalog, delegating to ``service``; ``guard`` protects every route."""

    router = APIRouter(tags=["Seed Catalog"], dependencies=[Depends(guard)] if guard else [])

    @router.get(
        "/v1/catalog/seed-tables",
        response_model=SeedCatalog,
        status_code=200,
        summary="Read the generated seed contract catalog, optionally filtered by table.",
    )
    async def get_seed_catalog(
        table: Annotated[str | None, Query(alias="table")] = None,
    ) -> SeedCatalog:
        return await service.get_seed_catalog(table=table)

    return router
